D={
82046:("since + oração","**Since** + momento de início, com **present perfect**.",[("I {{have worked}} here {{since}} last year.","Trabalho aqui desde o ano passado."),("Life {{has changed}} since I {{got}} the job.","A vida mudou desde que consegui o emprego."),("{{Since then}}, things have improved.","Desde então, as coisas melhoraram."),("I've been grateful {{since}} I started.","Sou grato desde que comecei.")],"Qual está certa?",["since I started","since I have started","since I will start"],0,"Since + passado simples."),
82047:("Deduzir pelo que vê","**Have/has been + -ing** explica o que você vê agora.",[("You're sweaty. You {{have been running}}.","Você está suado. Esteve correndo."),("The grass is wet. It {{has been raining}}.","A grama está molhada. Esteve chovendo."),("{{Have you been running}}?","Você esteve correndo?"),("You look exhausted. {{What have you been doing}}?","Você parece exausto. O que tem feito?")],"Que evidência combina: “It has been raining”?",["Rua molhada","Rua seca","Rua vazia"],0,"A chuva deixou rastros."),
82048:("Quantas vezes","**How many times have you + particípio?** Resposta: *once, twice, three times*.",[("{{How many times}} have you seen it?","Quantas vezes você viu?"),("I {{have seen}} it {{three times}}.","Vi três vezes."),("I've done the same thing {{again and again}}.","Fiz a mesma coisa de novo e de novo."),("I {{have been}} here {{twice}}.","Já estive aqui duas vezes.")],"Como dizer “duas vezes”?",["twice","two time","second"],0,"Twice."),
930010:("learn the ropes","**Learn the ropes** = aprender o básico; **on the ball** = atento; **up to speed** = atualizado; **get the hang of it** = pegar o jeito.",[("I'm {{learning the ropes}} this week.","Estou aprendendo como funciona esta semana."),("You'll {{get the hang of}} this job.","Você vai pegar o jeito deste trabalho."),("You're {{on the ball}} with the project.","Você está atento ao projeto."),("Let me bring you {{up to speed}}.","Deixe-me atualizá-lo.")],"“Get the hang of it” significa…",["pegar o jeito","pendurar","desistir"],0,"Dominar aos poucos."),
82049:("Experiência profissional","**Have/has + particípio**; com **for / since** para duração.",[("I {{have managed}} a big team.","Já gerenciei uma equipe grande."),("She {{has worked}} here {{for}} five years.","Ela trabalha aqui há cinco anos."),("We {{have never missed}} a deadline.","Nunca perdemos um prazo."),("He {{has been}} promoted twice.","Ele foi promovido duas vezes.")],"Complete: “She has worked here ___ 2018.”",["for","since","ago"],1,"Ponto no tempo: since."),
82050:("Saúde recente","**Present perfect** para mudanças recentes: *I have lost weight. I haven't slept well.*",[("I {{have had}} a headache.","Estive com dor de cabeça."),("I {{haven't slept}} well lately.","Não tenho dormido bem ultimamente."),("She {{has lost}} some weight.","Ela perdeu algum peso."),("{{Have you seen}} a doctor?","Você consultou um médico?")],"Qual é o particípio de “lose”?",["losed","lost","loss"],1,"Lose, lost, lost."),
82051:("Progresso no aprendizado","**Present perfect** para progresso; **for/since** para duração.",[("My vocabulary {{has grown}} a lot.","Meu vocabulário cresceu muito."),("I {{have studied}} English {{for}} two years.","Estudo inglês há dois anos."),("She {{has worked on}} her accent.","Ela trabalhou o sotaque."),("I {{have learned}} from my mistakes.","Aprendi com meus erros.")],"Qual está certa?",["I study English since 2022.","I have studied English since 2022.","I studied English since 2022."],1,"Since pede present perfect."),
82052:("Mudar de país","**Present perfect** para o que mudou desde a mudança; **get used to + -ing**.",[("We {{have moved}} to a new country.","Nos mudamos para um novo país."),("It {{has been}} challenging.","Tem sido desafiador."),("I {{have felt}} homesick.","Tenho sentido saudade de casa."),("I'm {{getting used to}} living here.","Estou me acostumando a viver aqui.")],"“Get used to” significa…",["usar","se acostumar","acostumar-se a pagar"],1,"Get used to = acostumar-se."),
82053:("Relacionamentos","**Present perfect** com **since / for**: *They have been engaged since June.*",[("They {{have been engaged}} since June.","Eles estão noivos desde junho."),("We {{have been dating}} for a year.","Estamos namorando há um ano."),("They {{have grown apart}}.","Eles se distanciaram."),("They {{have reunited}} after years.","Eles se reencontraram depois de anos.")],"“Grow apart” significa…",["crescer juntos","se distanciar","se casar"],1,"Distanciar-se."),
930011:("Dar más notícias","Suavize: **I'm afraid…**, **Unfortunately…**, **I'm sorry to tell you…**",[("{{I'm afraid}} we must close.","Receio que precisemos fechar."),("{{Unfortunately}}, the company can't help.","Infelizmente, a empresa não pode ajudar."),("{{I'm sorry to tell you}} it's over.","Sinto dizer que acabou."),("{{I'm afraid}} there's been a mistake.","Receio que houve um engano.")],"Qual suaviza a má notícia?",["It's over.","I'm afraid it's over.","Over it is."],1,"I'm afraid suaviza."),
82054:("Dinheiro","**Present perfect** para o balanço: *I have saved a lot. I haven't paid yet.*",[("I {{have saved}} a lot this year.","Economizei muito este ano."),("We {{have paid off}} the loan.","Quitamos o empréstimo."),("I {{haven't been able to}} afford a car.","Não consegui comprar um carro."),("She {{has invested}} in stocks.","Ela investiu em ações.")],"“Pay off” significa…",["quitar","pagar mais","gastar"],0,"Pay off = quitar."),
82055:("have been to","**Have been to** para lugares; **have + particípio** para atividades.",[("I {{have been to}} six countries.","Já estive em seis países."),("She {{has never tried}} bungee jumping.","Ela nunca tentou bungee jump."),("We {{have visited}} a small island.","Visitamos uma ilha pequena."),("{{Have you ever been}} to Peru?","Você já esteve no Peru?")],"Qual está certa?",["I have been in Peru twice.","I have been to Peru twice.","I have gone to Peru twice."],1,"Been to."),
82056:("Dar notícias","O **present perfect** é o tempo das notícias; os detalhes vão para o **passado**.",[("{{Have you heard}} the news?","Você ouviu a notícia?"),("He {{has quit}} his job.","Ele pediu demissão."),("Prices {{have dropped}} this week.","Os preços caíram esta semana."),("It happened {{last night}}.","Aconteceu ontem à noite.")],"Qual vem depois da notícia?",["have + particípio","um detalhe no passado simples","will + verbo"],1,"Detalhes: simple past."),
82057:("O tempo passa","**Present perfect** com **for, since, ago**; **How long has it been?**",[("Time {{has flown}} by.","O tempo voou."),("{{It has been}} ten years.","Já se passaram dez anos."),("We {{have known}} each other {{since}} 2015.","Nos conhecemos desde 2015."),("{{How long has it been}}?","Há quanto tempo?")],"Complete: “It has been ten years ___ we met.”",["since","for","ago"],0,"Since we met."),
82058:("Metas atingidas","**Present perfect** para resultados: *I have achieved my goal.*",[("I {{have achieved}} my goal.","Atingi meu objetivo."),("We {{have finally reached}} the top.","Finalmente chegamos ao topo."),("It {{has taken}} a lot of effort.","Exigiu muito esforço."),("It was {{worth}} it.","Valeu a pena.")],"“Finally” marca…",["o fim de um esforço","o começo","uma dúvida"],0,"Finally."),
930012:("carry out / carry on","**Carry out** = executar; **carry on** = continuar; **carry off** = conseguir; **carry over** = transferir.",[("We {{carry out}} an experiment.","Realizamos um experimento."),("We'll {{carry on}} despite the danger.","Continuaremos apesar do perigo."),("He {{carried off}} the task.","Ele conseguiu realizar a tarefa."),("Please {{carry over}} the notes.","Transfira as anotações, por favor.")],"“Carry on” significa…",["continuar","carregar","parar"],0,"Carry on = continuar."),
81287:("have been + -ing","Ação que começou e continua: **have/has been + verbo-ing**.",[("I {{have been climbing}} for an hour.","Estou subindo há uma hora."),("She {{has been trying}} all day.","Ela tenta o dia todo."),("{{How long have you been climbing}}?","Há quanto tempo você sobe?"),("We {{have been working}} hard.","Temos trabalhado duro.")],"Complete: “I ___ waiting for an hour.”",["have been","has been","am"],0,"I: have been."),
82059:("Hábitos que continuam","**Have/has been + -ing** para algo que começou antes e continua; foco na duração.",[("I {{have been exercising}} every day.","Tenho me exercitado todo dia."),("She {{has been running}} for six months.","Ela corre há seis meses."),("{{How long have you been exercising}}?","Há quanto tempo você se exercita?"),("The habit {{has stuck}}.","O hábito pegou.")],"“For six months” indica…",["duração","momento","frequência"],0,"For + período."),
82060:("Perguntas no present perfect","**Have/Has + sujeito + particípio?** Respostas: *Yes, I have. / No, I haven't.*",[("{{Have you finished}} yet?","Você já terminou?"),("{{Has she ever met}} a vampire?","Ela já conheceu um vampiro?"),("Yes, I {{have}}.","Sim, já."),("No, I {{haven't}}.","Não.")],"Qual está certa?",["Has she meet?","Has she met?","Did she met?"],1,"Has + particípio."),
82061:("Retomar contato","**Haven't + particípio** para o que não aconteceu; **have + particípio** para sentimentos.",[("I {{haven't called}} you.","Não liguei para você."),("My life {{has been}} so hectic.","Minha vida tem sido muito corrida."),("I {{have missed}} you.","Senti sua falta."),("I'm sorry I {{haven't been}} in touch.","Desculpe por não ter dado notícias.")],"Como pedir desculpas pelo silêncio?",["I'm sorry I haven't been in touch.","I'm sorry I didn't touch.","I sorry no touch."],0,"Haven't been in touch."),
930013:("collocations com do","**Do** combina com *research, business, damage, justice, homework*; **make** com *decision, mistake, plan, progress*.",[("I {{do research}} every day.","Faço pesquisa todo dia."),("They {{do business}} with us.","Eles fazem negócios conosco."),("A mistake can {{do damage}}.","Um erro pode causar dano."),("We {{make progress}} slowly.","Progredimos devagar.")],"Qual combina com “research”?",["make","do","get"],1,"Do research."),
82062:("Present perfect passivo","**Has/have been + particípio**: foco no resultado.",[("The map {{has been found}}.","O mapa foi encontrado."),("The doors {{have been closed}}.","As portas foram fechadas."),("The gold {{has been guarded}} by a dragon.","O ouro tem sido guardado por um dragão."),("{{Has}} the treasure {{been taken}}?","O tesouro foi levado?")],"Qual está no passivo?",["They have found it.","It has been found.","It has found."],1,"Has been + particípio."),
82063:("nearly / almost / not quite","**Nearly / almost** = quase; **not quite** = ainda não bem; **not yet** = ainda não.",[("I {{have nearly finished}}.","Quase terminei."),("We are {{almost}} there.","Estamos quase lá."),("Are you done? {{Not quite yet}}.","Terminou? Ainda não totalmente."),("{{Another}} step to go.","Mais um passo.")],"“Not quite” significa…",["totalmente","quase, mas não","nunca"],1,"Quase, mas ainda não."),
82064:("Revisão do present perfect","**Experiência, resultado, duração, passivo, perguntas**.",[("He {{has sailed}} to an island.","Ele já navegou até uma ilha."),("I {{have lived}} here for years.","Moro aqui há anos."),("The supper {{has been kept}} warm.","O jantar foi mantido aquecido."),("{{Have you ever}} wanted to leave?","Você já quis partir?")],"Qual mostra duração?",["I have lived here for years.","I have lost my keys.","Have you been there?"],0,"For years."),
82065:("will × going to","**Going to** = plano decidido; **will** = decisão na hora.",[("I'm {{going to start}} a business.","Vou abrir um negócio."),("I'{{ll}} help you now.","Eu ajudo você agora."),("{{Are you going to}} move next year?","Você vai se mudar ano que vem?"),("I {{intend to}} study abroad.","Pretendo estudar no exterior.")],"Qual é decisão na hora?",["I'm going to call him.","I'll call him now!","I'll be calling him."],1,"Decisão imediata: will."),
82066:("Future continuous","**Will be + -ing**: algo em andamento num ponto do futuro.",[("This time tomorrow, I'll {{be flying}}.","A esta hora amanhã estarei voando."),("Next year, she'll {{be living}} abroad.","Ano que vem, ela estará morando fora."),("{{Will you be working}} then?","Você estará trabalhando então?"),("No, I {{won't}}.","Não, não estarei.")],"Qual está certa?",["I will be work.","I will be working.","I will working."],1,"Will be + -ing."),
930014:("Emoções com preposição","**Proud of, grateful for, anxious about, disappointed in/with**.",[("I'm so {{relieved}} about the trip.","Estou tão aliviado com a viagem."),("He felt {{embarrassed}} about it.","Ele ficou constrangido com isso."),("I'm {{proud of}} your help.","Tenho orgulho da sua ajuda."),("She is {{anxious about}} the exam.","Ela está ansiosa com a prova.")],"Complete: “I'm grateful ___ your help.”",["of","for","at"],1,"Grateful for."),
82067:("Future perfect","**Will have + particípio**: concluído até um ponto do futuro.",[("By 2030, I'll {{have saved}} a lot.","Até 2030, terei economizado muito."),("She'll {{have graduated}} by June.","Ela terá se formado até junho."),("{{Will you have finished}} by Friday?","Você terá terminado até sexta?"),("I {{won't have finished}} by then.","Não terei terminado até lá.")],"“By Friday” combina com…",["will have + particípio","going to","used to"],0,"Concluído até."),
82068:("Presente contínuo: futuro","Compromissos combinados: **present continuous**.",[("I'm {{meeting}} Tom tomorrow.","Vou me encontrar com o Tom amanhã."),("We're {{having}} dinner on Friday.","Vamos jantar na sexta."),("She's {{flying}} to Rome next week.","Ela vai voar para Roma na semana que vem."),("I'm {{seeing}} the doctor at ten.","Vou ao médico às dez.")],"Qual é um compromisso marcado?",["I'm meeting him at six.","I will meet him maybe.","I meet him."],0,"Horário e pessoa definidos."),
82069:("Presente simples: horários","Horários fixos usam **present simple**.",[("The train {{leaves}} at eight.","O trem sai às oito."),("The class {{starts}} at ten.","A aula começa às dez."),("{{What time does}} the train {{leave}}?","A que horas sai o trem?"),("The film {{ends}} at nine.","O filme termina às nove.")],"Qual está certa?",["The train will leaves.","The train leaves at eight.","The train leave at eight."],1,"It leaves."),
82070:("will: ofertas e promessas","**I'll** para oferecer ajuda na hora e prometer; negativa **won't**.",[("{{I'll carry}} it for you.","Eu carrego para você."),("I promise {{I'll call}} you tonight.","Prometo que ligo hoje à noite."),("I {{won't be}} late.","Não vou me atrasar."),("{{I'll}} help you with that.","Ajudo você com isso.")],"“I won't” significa…",["I will not","I would","I want"],0,"Won't = will not."),
82071:("going to com evidência","**Going to** prevê com base no que você vê agora.",[("Look at those clouds! It's {{going to rain}}.","Olhe aquelas nuvens! Vai chover."),("Watch out! We're {{going to crash}}.","Cuidado! Vamos bater."),("{{Are we going to be}} okay?","Vamos ficar bem?"),("The sky is dark. A storm is {{going to}} hit.","O céu está escuro. Uma tempestade vai chegar.")],"Por que “going to” aqui?",["Há sinais à vista.","É uma promessa.","É um horário."],0,"Evidência atual."),
930015:("cut down on / cut out","**Cut down on** = reduzir; **cut out** = eliminar; **cut off** = cortar; **cut up** = picar.",[("I {{cut down on}} snacks.","Reduzi os lanches."),("I {{cut out}} candy.","Cortei os doces."),("They {{cut off}} the supply.","Cortaram o fornecimento."),("{{Cut up}} the fruit.","Pique a fruta.")],"“Cut out sugar” significa…",["reduzir um pouco","eliminar","picar"],1,"Eliminar."),
82072:("may / might / could","**May, might, could + verbo base** = possibilidade.",[("It {{might rain}} tomorrow.","Pode ser que chova amanhã."),("She {{could be}} late.","Ela pode se atrasar."),("He will {{probably}} choose the right door.","Provavelmente ele escolherá a porta certa."),("It {{might not}} work.","Pode ser que não funcione.")],"Qual é mais provável?",["It might rain.","It will probably rain.","It could rain."],1,"Probably."),
81337:("might / may","**Might / may + verbo** = possível, incerto.",[("I {{might have}} a cold.","Posso estar resfriado."),("You {{may have}} a fever.","Você pode estar com febre."),("It {{might rain}} tomorrow.","Pode chover amanhã."),("She {{may need}} rest.","Ela pode precisar de repouso.")],"Qual está certa?",["She might to rest.","She might rest.","She mights rest."],1,"Might + verbo base."),
82073:("hope / expect / look forward to","**Hope + oração**; **expect to + verbo**; **look forward to + -ing**.",[("{{I hope}} you can come.","Espero que você possa vir."),("{{I expect to}} hear from him.","Espero ter notícias dele."),("{{I look forward to seeing}} you.","Estou ansioso para ver você."),("{{Fingers crossed}}!","Torcendo!")],"Qual está certa?",["I look forward to see.","I look forward to seeing.","I look forward see."],1,"To + -ing."),
82074:("in case","**In case + presente** = por precaução; **in case of + substantivo**.",[("Take an umbrella {{in case}} it rains.","Leve guarda-chuva caso chova."),("I made a backup {{just in case}}.","Fiz backup por via das dúvidas."),("{{In case of}} fire, call 911.","Em caso de incêndio, ligue 911."),("Keep a spare key {{in case}} you lose yours.","Guarde uma chave reserva caso perca a sua.")],"Qual está certa?",["in case it will rain","in case it rains","in case it rained will"],1,"In case + presente."),
82075:("I'll × I've decided to","**I'll** = decisão agora; **I've decided to** = decisão já tomada.",[("{{I'll}} have the soup.","Vou querer a sopa."),("{{I've decided to}} quit my job.","Decidi largar meu emprego."),("{{I've made up my mind}}.","Já me decidi."),("{{I'll}} think about it.","Vou pensar nisso.")],"Qual é decisão já tomada?",["I'll go.","I've decided to go.","I might go."],1,"Decided."),
930016:("in the same boat","**In the same boat** = mesma situação; **pull your weight** = fazer sua parte; **on the same page** = alinhado.",[("We're all {{in the same boat}}.","Estamos todos no mesmo barco."),("{{Pull your weight}} on this team.","Faça sua parte nesta equipe."),("Are we {{on the same page}}?","Estamos alinhados?"),("The team {{works}} together.","A equipe trabalha junta.")],"“On the same page” significa…",["na mesma página","de acordo","no mesmo lugar"],1,"Alinhados."),
82076:("Orações de tempo","Depois de **when, before, until, as soon as**, use o **presente** (nunca *will*).",[("I'll call you {{when I arrive}}.","Ligo para você quando chegar."),("Call me {{before}} you leave.","Ligue-me antes de sair."),("Wait here {{until}} I come back.","Espere aqui até eu voltar."),("{{As soon as}} I get home, I'll rest.","Assim que chegar, descanso.")],"Qual está certa?",["when I will arrive","when I arrive","when I arrived"],1,"When + presente."),
82077:("will: previsões","**Will / won't** para previsões; *I think…*, *I doubt…* dão opinião.",[("Robots {{will do}} most jobs.","Robôs farão a maioria dos trabalhos."),("People {{won't need}} cash.","As pessoas não precisarão de dinheiro vivo."),("{{I doubt}} we'll live on Mars.","Duvido que moremos em Marte."),("{{I think}} it will change.","Acho que mudará.")],"“I doubt” expressa…",["certeza","dúvida","ordem"],1,"Doubt = dúvida."),
82078:("Combinar planos","Sugerir: **Let's / Shall we / How about**. Aceitar: **Works for me**.",[("{{Shall we}} meet at six?","Vamos nos encontrar às seis?"),("That {{works for me}}.","Para mim está bom."),("{{How about}} walking instead?","Que tal caminharmos?"),("{{Sounds good}}!","Parece bom!")],"Qual aceita a sugestão?",["Works for me.","I'd rather not.","No way."],0,"Works for me."),
82079:("Previsão + razão","Dê a previsão e a razão: *Prices will rise because demand is high.*",[("Prices {{will rise}} next year.","Os preços subirão ano que vem."),("It will rise {{because}} demand is high.","Vai subir porque a demanda é alta."),("{{I'm sure}} it will work.","Tenho certeza de que vai funcionar."),("{{Who knows}}?","Quem sabe?")],"Qual abre a razão?",["because","maybe","I doubt"],0,"Because."),
82080:("Revisão do futuro","**Will**: decisão, previsão; **going to**: plano; **contínuo**: compromisso; **future perfect**: concluído até; **simples**: horários.",[("I'm {{going to}} start a diet.","Vou começar uma dieta."),("I'{{ll}} call you later.","Ligo depois."),("We're {{leaving}} in the morning.","Partimos de manhã."),("The train {{leaves}} at nine.","O trem parte às nove.")],"Qual é um horário fixo?",["The train leaves at nine.","I'll leave.","I'm going to leave."],0,"Present simple."),
930017:("Gírias de cansaço","**Beat, wiped out, fried, zonked** = muito cansado (informal).",[("I'm {{beat}} after work.","Estou exausto depois do trabalho."),("I feel {{fried}} after that.","Estou acabado depois disso."),("I'll {{hit the sack}} early.","Vou dormir cedo."),("She's totally {{wiped out}}.","Ela está totalmente acabada.")],"“I'm beat” significa…",["estou animado","estou exausto","estou com fome"],1,"Exausto."),
82081:("Zero conditional","Fatos e verdades gerais: **if + presente, presente**.",[("If you heat ice, it {{melts}}.","Se você aquece gelo, ele derrete."),("If it's cold, I {{wear}} a coat.","Se faz frio, uso casaco."),("If you freeze water, you {{get}} ice.","Se congela água, obtém gelo."),("{{When}} water boils, it turns to steam.","Quando a água ferve, vira vapor.")],"Qual é fato geral?",["If I heat ice, it will melt tomorrow.","If you heat ice, it melts.","If I heated ice, it melted."],1,"Presente + presente."),
82082:("First conditional","Possibilidade real no futuro: **if + presente, will + verbo**.",[("If it rains, we'{{ll cancel}}.","Se chover, cancelaremos."),("If you're late, you'{{ll miss}} the train.","Se atrasar, perderá o trem."),("If I invite her, she'{{ll come}}.","Se eu convidar, ela virá."),("{{Unless}} you hurry, you'll be late.","A menos que se apresse, atrasará.")],"“Unless” significa…",["if not","if so","also"],0,"Unless = if not."),
82083:("Second conditional","Situações imaginárias: **if + passado, would + verbo**.",[("If I {{won}} the lottery, I'd travel.","Se eu ganhasse na loteria, viajaria."),("If I {{were}} you, I'd apologize.","Se eu fosse você, pediria desculpas."),("What {{would you do}} if you won?","O que você faria se ganhasse?"),("I {{would}} help if I could.","Eu ajudaria se pudesse.")],"Qual está certa?",["If I would win, I'd travel.","If I won, I'd travel.","If I win, I'd travel."],1,"If + passado, would."),
81163:("If I had…, I would…","Imaginação: **if + passado, would + verbo**.",[("If I {{had}} a dress, I {{would go}}.","Se eu tivesse um vestido, eu iria."),("If I {{had}} time, I {{would stay}}.","Se eu tivesse tempo, ficaria."),("The fairy {{has}} magic.","A fada tem magia."),("If I {{were}} rich, I'd buy a castle.","Se eu fosse rico, compraria um castelo.")],"Complete: “If I ___ time, I would help.”",["have","had","will have"],1,"Passado."),
82084:("Third conditional","Passado que não aconteceu: **if + had + particípio, would have + particípio**.",[("If I {{had practiced}}, I'd {{have passed}}.","Se eu tivesse praticado, teria passado."),("If I {{hadn't missed}} it, I'd have arrived.","Se eu não tivesse perdido, teria chegado."),("She {{would have taken}} the chance.","Ela teria aproveitado a chance."),("It {{would have been}} different.","Teria sido diferente.")],"Complete: “If I ___ studied, I would have passed.”",["had","have","would"],0,"If + had."),
930018:("fill in / fill out","**Fill in / fill out** = preencher; **fill up** = encher; **fill in for** = substituir.",[("{{Fill out}} the form.","Preencha o formulário."),("{{Fill up}} the printer.","Encha a impressora."),("I'll {{fill in for}} him on Monday.","Eu o substituo na segunda."),("{{Fill in}} the blanks.","Preencha as lacunas.")],"“Fill in for” significa…",["substituir","encher","preencher"],0,"Substituir."),
82085:("Condicionais mistas","**If + had + particípio, would + verbo**: causa no passado, resultado no presente.",[("If I {{had studied}}, I {{would be}} a doctor now.","Se eu tivesse estudado, seria médico agora."),("If I {{hadn't lied}}, I {{wouldn't be}} in trouble.","Se eu não tivesse mentido, não estaria em apuros."),("If we {{had talked}}, we'd be happier.","Se tivéssemos conversado, estaríamos mais felizes."),("If she {{had been}} braver, things would be different.","Se ela tivesse sido mais corajosa, as coisas seriam diferentes.")],"“Now” no resultado indica…",["condicional mista","zero conditional","first conditional"],0,"Passado → presente."),
82086:("wish + passado","**Wish + passado** para desejos irreais no presente. Com be: **were**.",[("I wish I {{could fly}}.","Queria poder voar."),("I wish I {{were}} taller.","Queria ser mais alto."),("I wish we {{lived}} closer.","Queria que morássemos mais perto."),("I wish I {{had}} a better voice.","Queria ter uma voz melhor.")],"Qual está certa?",["I wish I am taller.","I wish I were taller.","I wish I will be taller."],1,"Wish + were."),
81165:("I wish","Desejos: **I wish I were…** ou **I wish I could…**",[("I wish I {{were}} rich.","Queria ser rico."),("I wish I {{could fly}}.","Queria poder voar."),("The genie has {{three wishes}}.","O gênio tem três desejos."),("I wish I {{were}} free.","Queria ser livre.")],"Qual está certa?",["I wish I can fly.","I wish I could fly.","I wish I will fly."],1,"Wish + could."),
82087:("wish + past perfect","**Wish + had + particípio** lamenta o passado. **If only** é mais forte.",[("I wish I {{had studied}} abroad.","Queria ter estudado no exterior."),("{{If only}} I {{had spoken}} up!","Se ao menos eu tivesse falado!"),("I {{regret not telling}} her.","Lamento não ter contado a ela."),("I wish I {{hadn't gone}}.","Queria não ter ido.")],"“I wish I had studied” expressa…",["pedido","arrependimento","plano"],1,"Arrependimento."),
}
